const all=getAllOutstanding();
const total=all.reduce((s,r)=>s+r.outstanding,0);
return 'Total outstanding: Rs'+Math.round(total).toLocaleString('en-IN')+' across '+all.length+' customers';

const p=getPendingInvoices('Trupti');
if(!p.length) return 'No pending invoices for Trupti.';
const total=p.reduce((s,r)=>s+r.due,0);
return p.map(r=>r.date+' | '+r.invoice_id+' | Billed Rs'+r.billed+' | Due Rs'+r.due).join('\n')+'\nTotal due: Rs'+total+' across '+p.length+' invoice(s)';

const p=getPendingInvoices(null).filter(r=>r.date&&r.date.startsWith('2026-02'));
if(!p.length) return 'No unpaid invoices for Feb 2026.';
const total=p.reduce((s,r)=>s+r.due,0);
return p.map(r=>r.date+' | '+r.invoice_id+' | '+r.customer_name+' | Rs'+r.due).join('\n')+'\nTotal: '+p.length+' invoices, Rs'+total;

// Aggregate FIRST, then compute margin — never per-row
const rev={},cost={};
DATA.stock_out.filter(r=>r.sale_date&&r.sale_date.startsWith('2026-03')).forEach(r=>{
  rev[r.product_name]=(rev[r.product_name]||0)+(+r.total_sale||0);
  cost[r.product_name]=(cost[r.product_name]||0)+(+r.buying_rate_at_time||0);
});
return Object.keys(rev).filter(p=>rev[p]>0).map(p=>({p,margin:Math.round((rev[p]-cost[p])/rev[p]*100*10)/10})).sort((a,b)=>b.margin-a.margin).map(x=>x.p+': '+x.margin+'%').join('\n');

const ss=DATA.sales_summary;
const payMap={};// reference_invoice -> earliest PAY date
ss.filter(r=>String(r.reference_invoice_id||'').startsWith('PAY-')&&r.reference_invoice&&r.sale_date)
 .forEach(r=>{const ref=r.reference_invoice;if(!payMap[ref]||r.sale_date<payMap[ref])payMap[ref]=r.sale_date;});
const diffs=ss.filter(r=>!String(r.reference_invoice_id||'').startsWith('PAY-')&&payMap[r.reference_invoice_id])
 .map(r=>(new Date(payMap[r.reference_invoice_id])-new Date(r.sale_date))/86400000).filter(d=>d>=0&&d<365);
if(!diffs.length)return 'No matching payment records found.';
return 'Average collection period: '+Math.round(diffs.reduce((s,d)=>s+d,0)/diffs.length)+' days (from '+diffs.length+' matched invoices)';

const m={};
DATA.sales_summary.filter(r=>!String(r.reference_invoice_id||'').startsWith('PAY-')&&r.sale_date)
 .forEach(r=>{const k=r.sale_date.slice(0,7);m[k]=(m[k]||0)+(+r.total_bill||0);});
return Object.keys(m).sort().map(k=>k+': Rs'+Math.round(m[k]).toLocaleString('en-IN')).join('\n');

const d=new Date(DATA.exported_at.slice(0,7)+'-01T00:00:00');d.setMonth(d.getMonth()-1);
const month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); // last full calendar month, e.g. 2026-10
const rows=DATA.sales_summary.filter(r=>!String(r.reference_invoice_id||'').startsWith('PAY-')&&(r.sale_date||'').startsWith(month));
const total=rows.reduce((s,r)=>s+(+r.total_bill||0),0);
return 'Sales in '+month+': Rs'+Math.round(total).toLocaleString('en-IN')+' from '+rows.length+' invoices';

const d=new Date(DATA.exported_at.slice(0,7)+'-01T00:00:00');d.setMonth(d.getMonth()-1);
const month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); // last full calendar month, e.g. 2026-10
const rows=DATA.stock_out.filter(r=>(r.sale_date||'').startsWith(month));
const rev=rows.reduce((s,r)=>s+(+r.total_sale||0),0),cost=rows.reduce((s,r)=>s+(+r.buying_rate_at_time||0),0);
const gp=rev-cost;
return 'Month '+month+': Revenue Rs'+Math.round(rev).toLocaleString('en-IN')+', Cost Rs'+Math.round(cost).toLocaleString('en-IN')+', Gross profit Rs'+Math.round(gp).toLocaleString('en-IN')+' ('+(rev?(gp/rev*100).toFixed(1):0)+'% margin)';

const m={};
DATA.sales_summary.filter(r=>!String(r.reference_invoice_id||'').startsWith('PAY-'))
 .forEach(r=>{const l=custLocMap[r.customer_name]||'Unknown';m[l]=(m[l]||0)+(+r.total_bill||0);});
return Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([l,v])=>l+': Rs'+Math.round(v).toLocaleString('en-IN')).join('\n');

const m={};
DATA.sales_summary.filter(r=>!String(r.reference_invoice_id||'').startsWith('PAY-'))
 .forEach(r=>{m[r.customer_name]=(m[r.customer_name]||0)+(+r.total_bill||0);});
return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([c,v],i)=>(i+1)+'. '+c+': Rs'+Math.round(v).toLocaleString('en-IN')).join('\n');

const out=DATA.products.map(p=>getStockCoverDays(p.product_name)).filter(r=>!r.error&&typeof r.coverDays==='number'&&r.coverDays<7).sort((a,b)=>a.coverDays-b.coverDays);
if(!out.length) return 'No products with less than 7 days of stock.';
return out.map(r=>r.product+': '+r.currentStock+' units, '+r.coverDays+' days of cover (selling '+r.dailyRate+'/day)').join('\n');

const r=getPurchaseRecommendation(10,30);
if(!r.length) return 'Nothing to order — all products have 10+ days of cover.';
return r.map(x=>x.product+': buy '+x.boxesToBuy+' box(es) (cover '+x.coverDays+' days, est. Rs'+x.estimatedCost.toLocaleString('en-IN')+')').join('\n')+'\nEstimated total: Rs'+r.reduce((s,x)=>s+x.estimatedCost,0).toLocaleString('en-IN');

const r=getExpiringStock(45,DATA.exported_at.slice(0,10));
if(!r.length) return 'No stock expiring in the next 45 days.';
return r.map(x=>x.expiry_date+' ('+x.days_to_expiry+'d) | '+x.product_name+' | '+x.remaining_qty+' units | Rs'+x.total_cost).join('\n')+'\nTotal at cost: Rs'+r.reduce((s,x)=>s+x.total_cost,0);

const r=getExpiredStockWithRemaining();
if(!r.length) return 'No expired stock remaining.';
return r.map(x=>x.expiry_date+' | '+x.product_name+' | '+x.remaining_qty+' units | Rs'+x.total_cost).join('\n')+'\nTotal at cost: Rs'+r.reduce((s,x)=>s+x.total_cost,0);

const r=getLateCustomers(30,3);
if(!r.length) return 'No customers match the late-payer rule.';
return r.map(x=>x.customer+': late in '+x.monthCount+' months ('+x.months+')').join('\n');

const m={};DATA.expenses.forEach(e=>{m[e.spent_on]=(m[e.spent_on]||0)+(+e.total_expense||0);});
const total=Object.values(m).reduce((s,v)=>s+v,0);
return Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([k,v])=>k+': Rs'+Math.round(v).toLocaleString('en-IN')).join('\n')+'\nTotal: Rs'+Math.round(total).toLocaleString('en-IN');

const d=new Date(DATA.exported_at.slice(0,7)+'-01T00:00:00');d.setMonth(d.getMonth()-1);
const month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); // last full calendar month, e.g. 2026-10
let cash=0,upi=0;
DATA.sales_summary.filter(r=>(r.sale_date||'').startsWith(month)).forEach(r=>{cash+=+r.cash_received||0;upi+=+r.upi_received||0;});
return 'Collected in '+month+': Cash Rs'+Math.round(cash).toLocaleString('en-IN')+' + UPI Rs'+Math.round(upi).toLocaleString('en-IN')+' = Rs'+Math.round(cash+upi).toLocaleString('en-IN');

const name='PEPSI COLA 400ml PET30 Rs20';
const hits=DATA.products.filter(p=>p.product_name===name);
if(!hits.length) return 'No matching product.';
return hits.map(p=>{const boxes=Math.floor(p.current_stock/p.pack_size),bottles=p.current_stock%p.pack_size;return p.product_name+': '+p.current_stock+' units ('+boxes+' boxes + '+bottles+' bottles)';}).join('\n');

const name='Trupti';
const m={};
DATA.stock_out.filter(r=>r.customer_name===name).forEach(r=>{const x=m[r.product_name]||(m[r.product_name]={qty:0,amt:0});x.qty+=+r.quantity||0;x.amt+=+r.total_sale||0;});
const rows=Object.entries(m).sort((a,b)=>b[1].amt-a[1].amt);
if(!rows.length) return 'No purchases found for '+name+'.';
return rows.map(([p,x])=>p+': '+x.qty+' units, Rs'+Math.round(x.amt).toLocaleString('en-IN')).join('\n');

const name='Trupti';
const pays=DATA.sales_summary.filter(r=>r.customer_name===name&&String(r.reference_invoice_id||'').startsWith('PAY-')).sort((a,b)=>(b.sale_date||'').localeCompare(a.sale_date||''));
if(!pays.length) return 'No separate payments recorded for '+name+'.';
return pays.map(r=>r.sale_date+' | '+r.reference_invoice_id+' | cash Rs'+(+r.cash_received||0)+' | UPI Rs'+(+r.upi_received||0)+' | discount Rs'+(+r.discount_amount||0)).join('\n');

const d=new Date(DATA.exported_at.slice(0,7)+'-01T00:00:00');d.setMonth(d.getMonth()-1);
const month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); // last full calendar month, e.g. 2026-10
const name='PEPSI COLA 400ml PET30 Rs20';
const prod=DATA.products.find(p=>p.product_name===name);
const qty=DATA.stock_out.filter(r=>r.product_name===name&&(r.sale_date||'').startsWith(month)).reduce((s,r)=>s+(+r.quantity||0),0);
return name+' sold in '+month+': '+qty+' units'+(prod?' ('+(qty/(+prod.pack_size||1)).toFixed(1)+' boxes)':'');
